<?php require_once '../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$pts=(int)($_POST['points_required']??0);if($name!==''&&$pts>0){db()->prepare('INSERT INTO rewards(name,description,points_required) VALUES(?,?,?)')->execute([$name,$desc,$pts]);flash('Reward added.');}else flash('Enter a reward name and positive point value.','error');redirect('rewards.php');}$rows=db()->query('SELECT * FROM rewards ORDER BY points_required')->fetchAll();page_start('Manage rewards');?><section class="panel"><h2>Add a reward</h2><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Reward name<input name="name" required maxlength="120"></label><label>Description<textarea name="description" rows="2"></textarea></label><label>Points required<input type="number" name="points_required" min="1" required></label><button class="btn">Add reward</button></form></section><section class="panel"><h2>Current rewards</h2><table><tr><th>Name</th><th>Description</th><th>Points</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><?=e($r['points_required'])?></td><td><?=($r['active']?'Active':'Inactive')?></td></tr><?php endforeach;?></table></section><?php page_end();?>
